def keep_existing_choices(apps, schema_editor):
    Campaign = apps.get_model("campaigns", "Campaign")
    ConnectedAccount = apps.get_model("campaigns", "ConnectedAccount")
    for campaign in Campaign.objects.exclude(project=None).filter(developer=None).select_related("project"):
        campaign.developer_id = campaign.project.developer_id
        campaign.save(update_fields=["developer"])
    for campaign in Campaign.objects.filter(destination="connected_page"):
        handle = "@" + campaign.connected_page_handle.lstrip("@") if campaign.connected_page_handle else ""
        account = None
        if handle != "@" and handle:
            account, _ = ConnectedAccount.objects.get_or_create(
                office_id=campaign.office_id, platform="instagram", handle=handle,
                defaults={"added_by_id": campaign.created_by_id},
            )
        campaign.destination = "own_account"
        campaign.connected_account = account
        campaign.save(update_fields=["destination", "connected_account"])


def restore_choices(apps, schema_editor):
    Campaign = apps.get_model("campaigns", "Campaign")
    for campaign in Campaign.objects.filter(destination="own_account").select_related("connected_account"):
        campaign.destination = "connected_page"
        campaign.connected_page_handle = campaign.connected_account.handle if campaign.connected_account else ""
        campaign.save(update_fields=["destination", "connected_page_handle"])


